css:
:scope { width: min(100%, 4730px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 7; grid-row: 1 / span 3; font-family: var(--os-font-label); font-size: 17px; font-weight: 500; line-height: 1.53; letter-spacing: 0.353em; text-transform: uppercase; text-align: center; color: inherit; }
.gx__i2 { grid-column: 1 / span 7; grid-row: 5 / span 5; font-family: var(--os-font-heading); font-size: 30px; font-weight: 400; line-height: 1.4; letter-spacing: 0.28em; text-transform: uppercase; text-align: center; color: var(--os-color-text); }
.gx__i3 { grid-column: 6 / span 2; grid-row: 21 / span 16; aspect-ratio: 342 / 124; }
.gx__i4 { grid-column: 13 / span 2; grid-row: 21 / span 16; aspect-ratio: 342 / 124; }
.gx__i5 { grid-column: 21 / span 2; grid-row: 21 / span 16; aspect-ratio: 342 / 124; }
.gx__i6 { grid-column: 1 / span 1; grid-row: 24 / span 11; aspect-ratio: 224 / 90; }
.gx__i7 { grid-column: 3 / span 1; grid-row: 24 / span 11; aspect-ratio: 288 / 90; }
.gx__i8 { grid-column: 5 / span 1; grid-row: 25 / span 9; aspect-ratio: 154 / 74; }
.gx__i9 { grid-column: 8 / span 1; grid-row: 24 / span 11; aspect-ratio: 248 / 90; }
.gx__i10 { grid-column: 9 / span 1; grid-row: 24 / span 11; aspect-ratio: 224 / 90; }
.gx__i11 { grid-column: 11 / span 1; grid-row: 24 / span 11; aspect-ratio: 288 / 90; }
.gx__i12 { grid-column: 12 / span 1; grid-row: 25 / span 9; aspect-ratio: 154 / 74; }
.gx__i13 { grid-column: 15 / span 1; grid-row: 24 / span 11; aspect-ratio: 248 / 90; }
.gx__i14 { grid-column: 17 / span 1; grid-row: 24 / span 11; aspect-ratio: 224 / 90; }
.gx__i15 { grid-column: 18 / span 1; grid-row: 24 / span 11; aspect-ratio: 288 / 90; }
.gx__i16 { grid-column: 20 / span 1; grid-row: 25 / span 9; aspect-ratio: 154 / 74; }
.gx__i17 { grid-column: 23 / span 1; grid-row: 24 / span 11; aspect-ratio: 248 / 90; }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 24px; }
}
